<div class="breadcrumbs"><a href="<?= $link('/organizations/'.$organization['id']) ?>"><?= $e($organization['name']) ?></a><span>/</span><?= $e(['asset'=>'Configurations','article'=>'Documents','contact'=>'Contacts','location'=>'Locations'][$type]) ?></div>
<div class="section-actions"><p class="muted"><?= $trash?'Archived documentation can be restored.':'Documentation visible to your account.' ?></p><?php if($canWrite): ?><div><a class="text-link" href="<?= $link('/organizations/'.$organization['id'].'/'.$type.'?trash='.($trash?'0':'1')) ?>"><?= $trash?'Active records':'Archived records' ?></a> <a class="button" href="<?= $link('/organizations/'.$organization['id'].'/'.$type.'/new') ?>">+ New <?= $e(['asset'=>'configuration','article'=>'document','contact'=>'contact','location'=>'location'][$type]) ?></a></div><?php endif; ?></div>
<div class="card table-card"><?php if(!$records): ?><div class="empty-state"><h2>No <?= $e(['asset'=>'configuration','article'=>'document','contact'=>'contact','location'=>'location'][$type]) ?> records yet</h2><p><?= $canWrite?'Add a record to start documenting this organization.':'No records are available to your account.' ?></p></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Name</th><th>Category</th><th>Visibility</th><th>Updated (UTC)</th><?php if($trash): ?><th>Action</th><?php endif; ?></tr></thead><tbody><?php foreach($records as $r): ?><tr><td><?php if(!$trash): ?><a href="<?= $link('/records/'.$r['id']) ?>"><?= $e($r['title']) ?></a><?php else: ?><?= $e($r['title']) ?><?php endif; ?></td><td><?= $e($r['category']?:'—') ?></td><td><span class="badge <?= $r['visibility']==='client'?'shared':'' ?>"><?= $r['visibility']==='internal'?'Internal only':'Client visible' ?></span></td><td><?= $e($r['updated_at']) ?></td><?php if($trash): ?><td><form method="post" action="<?= $link('/records/'.$r['id'].'/restore') ?>"><?= $csrf ?><button class="button small secondary">Restore</button></form></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<div class="pagination"><?php if($page>1): ?><a href="<?= $link('/organizations/'.$organization['id'].'/'.$type.'?page='.($page-1).'&trash='.(int)$trash) ?>">← Previous</a><?php endif; ?><?php if(count($records)===50): ?><a href="<?= $link('/organizations/'.$organization['id'].'/'.$type.'?page='.($page+1).'&trash='.(int)$trash) ?>">Next →</a><?php endif; ?></div>
